const updatesPreference = `-- name: UpdatesPreference :one
SELECT CAST(COALESCE((SELECT enabled FROM account_update_preferences WHERE user_id=?),0) AS INTEGER) AS enabled
`

func (q *Queries) UpdatesPreference(ctx context.Context, userID string) (int64, error) {
	row := q.db.QueryRowContext(ctx, updatesPreference, userID)
	var enabled int64
	err := row.Scan(&enabled)
	return enabled, err
}

