const updatesSubscribers = `-- name: UpdatesSubscribers :many
SELECT u.id,u.email,u.display_name FROM users u JOIN account_update_preferences p ON p.user_id=u.id WHERE u.status='active' AND p.enabled=1
`

type UpdatesSubscribersRow struct {
	ID          string
	Email       string
	DisplayName string
}

func (q *Queries) UpdatesSubscribers(ctx context.Context) ([]UpdatesSubscribersRow, error) {
	rows, err := q.db.QueryContext(ctx, updatesSubscribers)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UpdatesSubscribersRow{}
	for rows.Next() {
		var i UpdatesSubscribersRow
		if err := rows.Scan(&i.ID, &i.Email, &i.DisplayName); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
